import utilSrv from "./js/base/utils"
if (navigator.serviceWorker) {
  navigator.serviceWorker.addEventListener('message', (event) => {
    utilSrv.Write(utilSrv.INFO, 'port-Bridge 接收端口');
    if (event.ports && event.ports.length > 0) {
      const port = event.ports[0]; //完成使命就移除
      window.parent.postMessage({ type: utilSrv.msgTypeBRIDGEPORT}, '*', [port]);
      utilSrv.Write(utilSrv.INFO, 'port-Bridge 端口转接');
      setTimeout(() => window.frameElement?.remove(), 100);
    }
  });
} else {
  utilSrv.Write(utilSrv.ERROR, 'port-Bridge serviceWorker不可用');
}
// 通知 background：bridge 已就绪
utilSrv.Write(utilSrv.INFO, 'port-Bridge就绪');
chrome.runtime.sendMessage({ type: utilSrv.msgTypeBRIDGEREADY});